name: LRPM isolated Storage and nationwide audit
on:
  push:
    branches: [verify/lrpm-storage-audit-220]
    paths: [.github/workflows/lrpm-isolated-audit-220.yml]
permissions:
  contents: read
  actions: read
jobs:
  audit:
    runs-on: ubuntu-latest
    timeout-minutes: 35
    steps:
      - uses: actions/checkout@v4
        with:
          ref: 4e3ef0080f5f08e568f51a07a70726cda4117f44
          persist-credentials: false
      - uses: actions/setup-node@v4
        with:
          node-version: 22
      - uses: supabase/setup-cli@v1
        with:
          version: 3.1.0
      - uses: actions/download-artifact@v4
        with:
          github-token: ${{ github.token }}
          run-id: 43653446881
          artifact-ids: 14136872031
          merge-multiple: true
          path: /tmp/lrpm-input
      - uses: actions/download-artifact@v4
        with:
          github-token: ${{ github.token }}
          run-id: 43602835654
          pattern: n03-*
          merge-multiple: true
          path: /tmp/n03-local
      - run: npm install --no-audit --no-fund
      - name: Verify prepared nationwide N03
        run: |
          mkdir -p /tmp/lrpm-evidence
          set -o pipefail
          npx tsx scripts/light-rain-nationwide-n03-audit.ts /tmp/n03-local --require-wards | tee /tmp/lrpm-evidence/n03.json
      - name: Start disposable Supabase with empty database
        run: |
          sandbox=$(mktemp -d)
          echo "LRPM_SANDBOX=$sandbox" >> "$GITHUB_ENV"
          cd "$sandbox"
          supabase init
          supabase start -x studio,imgproxy,inbucket,edge-runtime,logflare,vector,supavisor,realtime
      - name: Verify private upload and signed download through the existing loader
        env:
          LRPM_ARCHIVE_SHA256: 5fb0823f190e9ed893ba5ee9ae47aa7b1e4a8ad9c26601e2cae8b14bc1de33d8
        shell: bash
        run: |
          set -euo pipefail
          ulimit -c 0
          archive=/tmp/lrpm-input/lrpm-japan-20260101-v1.tar.gz
          echo "$LRPM_ARCHIVE_SHA256  $archive" | sha256sum --check
          tls=$(mktemp -d)
          export LRPM_TLS="$tls"
          openssl req -x509 -newkey rsa:2048 -nodes -days 1 -subj '/CN=localhost' -addext 'subjectAltName=DNS:localhost' -keyout "$tls/key.pem" -out "$tls/cert.pem" 2>/dev/null
          export NODE_EXTRA_CA_CERTS="$tls/cert.pem"
          node --input-type=module <<'JS' | tee /tmp/lrpm-evidence/storage.jsonl
          import { createClient } from '@supabase/supabase-js';
          import { execFileSync } from 'node:child_process';
          import { readFileSync } from 'node:fs';
          import { request } from 'node:http';
          import { createServer } from 'node:https';
          import { timingSafeEqual } from 'node:crypto';
          const sandbox = process.env.LRPM_SANDBOX;
          const status = JSON.parse(execFileSync('supabase', ['status', '-o', 'json'], { cwd: sandbox, encoding: 'utf8' }));
          const upstream = new URL(status.API_URL);
          if (upstream.origin !== 'http://127.0.0.1:54321') throw new Error('Expected disposable loopback Supabase');
          const key = status.SERVICE_ROLE_KEY ?? status.SECRET_KEY;
          if (!key) throw new Error('Missing local signing credential');
          const bucket = 'national-rain-lrpm-qa';
          const object = '20260101/v1/lrpm-japan-20260101-v1.tar.gz';
          const local = createClient(upstream.origin, key, { auth: { persistSession: false, autoRefreshToken: false } });
          const bytes = readFileSync('/tmp/lrpm-input/lrpm-japan-20260101-v1.tar.gz');
          function check(result, step) {
            if (result.error) throw new Error(step + ': ' + (result.error.statusCode ?? result.error.name));
            return result.data;
          }
          check(await local.storage.createBucket(bucket, { public: false, fileSizeLimit: 10485760 }), 'create private bucket');
          if (check(await local.storage.getBucket(bucket), 'inspect bucket').public !== false) throw new Error('Bucket should be private');
          check(await local.storage.from(bucket).upload(object, bytes, { contentType: 'application/gzip', upsert: false }), 'upload');
          const unsigned = await fetch(upstream.origin + '/storage/v1/object/public/' + bucket + '/' + object);
          if (unsigned.ok) throw new Error('Unsigned read unexpectedly succeeded');
          const signed = new URL(check(await local.storage.from(bucket).createSignedUrl(object, 180), 'sign').signedUrl);
          if (signed.origin !== upstream.origin || !signed.pathname.startsWith('/storage/v1/object/sign/') || !signed.searchParams.has('token')) throw new Error('Unexpected signed URL');
          const tls = process.env.LRPM_TLS;
          const bridge = createServer({ key: readFileSync(tls + '/key.pem'), cert: readFileSync(tls + '/cert.pem') }, (req, res) => {
            if (req.method !== 'GET' || !req.url.startsWith('/storage/v1/object/sign/')) { res.writeHead(404).end(); return; }
            const forward = request(new URL(req.url, upstream), result => {
              res.writeHead(result.statusCode, result.headers);
              result.pipe(res);
            });
            forward.on('error', () => res.writeHead(502).end());
            forward.end();
          });
          await new Promise(resolve => bridge.listen(4443, '127.0.0.1', resolve));
          try {
            const https = 'https://localhost:4443' + signed.pathname + signed.search;
            const response = await fetch(https);
            if (!response.ok) throw new Error('Signed read rejected: ' + response.status);
            const downloaded = Buffer.from(await response.arrayBuffer());
            if (downloaded.length !== bytes.length || !timingSafeEqual(downloaded, bytes)) throw new Error('Signed read did not return the original bytes');
            console.log(JSON.stringify({event: 'LRPM_PRIVATE_STORAGE_VERIFIED', unsignedStatus: unsigned.status, signedStatus: response.status, bytes: bytes.length}));
            const { spawn } = await import('node:child_process');
            for (const url of [https, 'https://localhost:4443/cache-reuse-does-not-download']) {
              const code = await new Promise((resolve, reject) => {
                const child = spawn('npx', ['tsx', 'scripts/light-rain-mask-prepare.ts', '/tmp/lrpm-cache'], {
                  stdio: 'inherit', env: { ...process.env, LRPM_ARCHIVE_URL: url }
                });
                child.on('error', reject);
                child.on('close', resolve);
              });
              if (code !== 0) throw new Error('LRPM preparation failed');
            }
          } finally {
            bridge.close();
          }
          JS
      - name: Measure consecutive nationwide five-minute slots
        timeout-minutes: 26
        env:
          JMA_Z10_PIXEL_MASK_DIR: /tmp/lrpm-cache/20260101-v1
          JMA_WATCH_SUCCESS_COUNT: "4"
          JMA_Z10_CONCURRENCY: "8"
        run: |
          set -o pipefail
          npx tsx scripts/light-rain-z10-refine.ts /tmp/n03-local --watch 2>&1 | tee /tmp/lrpm-evidence/watch.jsonl
      - uses: actions/upload-artifact@v4
        if: always()
        with:
          name: lrpm-isolated-audit-evidence
          path: /tmp/lrpm-evidence/
          retention-days: 7
      - name: Stop disposable Supabase
        if: always() && env.LRPM_SANDBOX != ''
        run: |
          cd "$LRPM_SANDBOX"
          supabase stop --no-backup

