/** Read-only real JMA forecast + official 2026 prefecture N03 municipality proof.
 * Coarse z4 tiles are a sampling proof, NOT nationwide coverage or final z10 accuracy.
 * No production Storage, notifications, or Bluesky calls.
 */
import { readFileSync } from "node:fs";
import { fetchForecastTargetTimes } from "../lib/weather/providers/jma/targetTimes";
import { buildJmaRainTileUrl } from "../lib/weather/providers/jma/tileUrl";
import { locateJmaRainPixelsAtLeast1mm, scanJmaTileAtLeast1mm } from "../lib/weather/rain/lightRainProof";
import { municipalitiesForLightRainTile } from "../lib/weather/rain/lightRainMunicipalities";
import { parseOfficialN03ForLightRain, type N03FeatureCollection } from "../lib/weather/rain/lightRainOfficialN03";

const file = process.argv[2];
const targetPrefecture = process.argv[3] ?? "東京都";
if (!file) throw new Error("Usage: npx tsx scripts/light-rain-jma-n03-live-proof.ts <official N03 GeoJSON> [prefecture]");
const collection = JSON.parse(readFileSync(file, "utf8")) as N03FeatureCollection;
const areas = parseOfficialN03ForLightRain(collection).filter(a => a.prefecture === targetPrefecture);
if (!areas.length) throw new Error("Official N03 missing administrative areas for "+targetPrefecture);
const tiles = [[13, 5], [14, 5], [13, 6], [14, 6], [13, 7], [14, 7]] as const;
const stamp = (v: string) => Date.UTC(Number(v.slice(0,4)), Number(v.slice(4,6))-1,
  Number(v.slice(6,8)), Number(v.slice(8,10)), Number(v.slice(10,12)));
async function fetchTileWithRetry(url: string, label: string): Promise<Buffer> {
  const attempts = 3;
  for (let attempt = 1; attempt <= attempts; attempt++) {
    try {
      const response = await fetch(url, {cache:"no-store",signal:AbortSignal.timeout(15000)});
      if (response.ok) return Buffer.from(await response.arrayBuffer());
      if (response.status !== 404 && response.status !== 429 && response.status < 500) throw new Error("Non-retryable JMA tile HTTP "+response.status+" "+label);
      if (attempt === attempts) throw new Error((response.status === 404 ? "INCOMPLETE_PROOF: missing JMA forecast tile HTTP 404 " : "JMA tile HTTP "+response.status+" ")+"after "+attempts+" attempts "+label);
    } catch (error) {
      if (attempt === attempts || String(error).includes("Non-retryable")) throw error;
    }
    await new Promise(resolve => setTimeout(resolve, 1000 * attempt));
  }
  throw new Error("Unreachable JMA retry state "+label);
}
async function main() {
  const now = Date.now();
  const frames = (await fetchForecastTargetTimes())
    .filter(f => stamp(f.validtime) > now && stamp(f.validtime) <= now + 30 * 60000).slice(0,6);
  if (!frames.length) throw new Error("No future JMA frames within 30 minutes");
  const results = [];
  for (const frame of frames) {
    const codes = new Map<string, { code: string; prefecture: string; municipality: string }>();
    let rainyPixels = 0;
    let rainyPixelsInTokyoMainlandBox = 0;
    const tileDiagnostics: Array<{x:number;y:number;rainyPixels:number;tokyoMainlandBoxPixels:number;sampleRainCoordinates:Array<{longitude:number;latitude:number}>}> = [];
    for (const [x,y] of tiles) {
      const buffer = await fetchTileWithRetry(buildJmaRainTileUrl(frame,4,x,y),frame.validtime+" z4/"+x+"/"+y);
      const scan = scanJmaTileAtLeast1mm(buffer);
      if (scan.unknownPixels) throw new Error("Unknown JMA palette pixel");
      rainyPixels += scan.rainPixels;
      const points = scan.rainPixels ? locateJmaRainPixelsAtLeast1mm(buffer,4,x,y) : [];
      const tokyoBox = points.filter(p => p.longitude >= 138.9 && p.longitude <= 140.2 && p.latitude >= 35.45 && p.latitude <= 35.9).length;
      rainyPixelsInTokyoMainlandBox += tokyoBox;
      tileDiagnostics.push({x,y,rainyPixels:scan.rainPixels,tokyoMainlandBoxPixels:tokyoBox,sampleRainCoordinates:points.filter((_,i)=>i%Math.max(1,Math.floor(points.length/3))===0).slice(0,3).map(p=>({longitude:Number(p.longitude.toFixed(3)),latitude:Number(p.latitude.toFixed(3))}))});
      if (!scan.rainPixels) continue;
      for (const area of municipalitiesForLightRainTile(buffer,4,x,y,areas)) codes.set(area.code,area);
    }
    results.push({validtime:frame.validtime,rainyPixels,rainyPixelsInTokyoMainlandBox,tileDiagnostics,municipalities:[...codes.values()]});
  }
  if (results.length !== 6) throw new Error("INCOMPLETE_PROOF: expected six 5-minute forecast frames, got "+results.length);
  if (results.every(r => r.rainyPixels === 0)) throw new Error("No real JMA >=1mm rain pixels in sample");
  if (results.every(r => r.municipalities.length === 0)) {
    console.log(JSON.stringify({status:"INCONCLUSIVE",reason:results.every(r=>r.rainyPixelsInTokyoMainlandBox===0) ? "No rain in Tokyo mainland bounding box at sampled frames (diagnostic only)" : "Rain in Tokyo bounding box but no official N03 intersection (diagnostic only)",frames:results}));
    throw new Error("INCOMPLETE_PROOF: no real rainy pixel intersected an official " + targetPrefecture + " municipality; do not claim municipality resolution");
  }
  console.log(JSON.stringify({mode:"REAL_JMA_OFFICIAL_N03_READ_ONLY",checkedAt:new Date().toISOString(),
    prefecture:targetPrefecture,threshold:">=1mm/h",zoom:4,tiles:tiles.length,frames:results,coverage:"six coarse tiles only",
    precision:"coarse pixel footprints; not suitable for publishing municipality alerts",
    municipalityIdentity:"use N03 code as key; municipality names alone are not unique (e.g. Sapporo wards)",
    productionWrites:false,blueskyPosts:false}));
}
main().catch(e=>{console.error(e);process.exitCode=1;});

